<script setup>import {ref,reactive,onMounted} from 'vue';import {api,money,labels,toast,upload,time} from '../core';import State from '../components/State.vue';const tab=ref('users'),loading=ref(false),error=ref(''),busy=ref(false),users=ref({items:[],total:0}),products=ref({items:[],total:0}),orders=ref([]),query=ref(''),status=ref(''),page=ref(1),selected=ref(null),reason=ref(''),message=reactive({title:'',body:''}),editing=ref(false),editingId=ref(null),shipping=reactive({}),operation=ref(null),product=reactive({name:'',category:'主粮',description:'',image:'',price:100,stock:10,listed:true,recommended:false,version:0}),priceYuan=ref('1.00');async function load(){loading.value=true;error.value='';try{if(tab.value==='users')users.value=await api('/admin/users?'+new URLSearchParams({accountContains:query.value,page:page.value,size:10,...(status.value?{status:status.value}:{})}));if(tab.value==='products')products.value=await api('/admin/products?'+new URLSearchParams({keyword:query.value,page:page.value}));if(tab.value==='orders')orders.value=await api('/admin/orders')}catch(e){error.value=e.message}finally{loading.value=false}}function switchTab(t){tab.value=t;query.value='';page.value=1;selected.value=null;load()}async function select(u){try{selected.value=await api('/admin/users/'+u.id);reason.value='';message.title='';message.body='';operation.value=null}catch(e){toast(e.message,true)}}async function command(kind){busy.value=true;try{const payload=kind==='state'?{expectedStateVersion:selected.value.stateVersion,targetStatus:selected.value.status==='ACTIVE'?'FROZEN':'ACTIVE',reason:reason.value}:{title:message.title,body:message.body};const key=JSON.stringify([selected.value.id,kind,payload]);if(operation.value?.key!==key)operation.value={key,id:crypto.randomUUID()};await api('/admin/users/'+selected.value.id+'/'+(kind==='state'?'state':'notifications'),'POST',{...payload,operationId:operation.value.id});toast('管理操作已保存');const target=selected.value.id;await load();selected.value=await api('/admin/users/'+target);operation.value=null}catch(e){toast(e.message,true);if(e.status===409){selected.value=await api('/admin/users/'+selected.value.id);operation.value=null}}finally{busy.value=false}}function edit(p){editingId.value=p?.id||null;Object.assign(product,p?{name:p.name,category:p.category,description:p.description,image:p.image,price:p.price,stock:p.stock,listed:!!p.listed,recommended:!!p.recommended,version:p.version}:{name:'',category:'主粮',description:'',image:'',price:100,stock:10,listed:true,recommended:false,version:0});priceYuan.value=(product.price/100).toFixed(2);editing.value=true}async function photo(e){if(!e.target.files[0])return;busy.value=true;try{product.image=await upload(e.target.files[0])}catch(e){toast(e.message,true)}finally{busy.value=false}}async function saveProduct(){busy.value=true;try{if(!/^\d+(\.\d{1,2})?$/.test(priceYuan.value))throw new Error('价格最多两位小数');const [whole,decimal='']=priceYuan.value.split('.');const price=Number(whole)*100+Number(decimal.padEnd(2,'0'));await api('/admin/products'+(editingId.value?'/'+editingId.value:''),editingId.value?'PUT':'POST',{...product,price});editing.value=false;toast('商品已保存');await load()}catch(e){toast(e.message,true)}finally{busy.value=false}}async function ship(o){busy.value=true;try{await api('/admin/orders/'+o.id+'/ship','POST',shipping[o.id]||{carrier:'',tracking:''});toast('已确认发货');await load()}catch(e){toast(e.message,true)}finally{busy.value=false}}onMounted(load);</script><template><section class="shell section admin-page"><p class="eyebrow">PET HAVEN / MANAGEMENT</p><h1>管理中心</h1><p class="muted">认真核对每一次操作，让平台有序运转。</p><div class="tabs"><button :class="{active:tab==='users'}" @click="switchTab('users')">用户管理</button><button :class="{active:tab==='products'}" @click="switchTab('products')">商品管理</button><button :class="{active:tab==='orders'}" @click="switchTab('orders')">订单与发货</button></div><form v-if="tab!=='orders'" class="filter-bar" @submit.prevent="page=1;load()"><input v-model="query" :placeholder="tab==='users'?'搜索用户账号':'搜索商品名称'" aria-label="管理查询"><select v-if="tab==='users'" v-model="status" aria-label="账号状态"><option value="">全部状态</option><option value="ACTIVE">正常</option><option value="FROZEN">已冻结</option></select><button class="btn small">查询</button><button v-if="tab==='products'" type="button" class="btn secondary small" @click="edit(null)">＋ 新增商品</button></form><State :loading="loading" :error="error" @retry="load"/><template v-if="!loading&&!error"><div v-if="tab==='users'" class="table-wrap panel"><table><thead><tr><th>账号 / 昵称</th><th>角色</th><th>状态</th><th>加入时间</th><th>操作</th></tr></thead><tbody><tr v-for="u in users.items" :key="u.id"><td><strong>{{u.account}}</strong><small>{{u.nickname}}</small></td><td>{{u.role}}</td><td><span class="badge" :class="{warning:u.status==='FROZEN'}">{{labels[u.status]}}</span></td><td>{{time(u.createdAt)}}</td><td><button class="text-button" @click="select(u)">核对详情 →</button></td></tr></tbody></table><p v-if="!users.items.length" class="state">没有匹配用户</p></div><div v-if="tab==='products'" class="table-wrap panel"><table><thead><tr><th>商品</th><th>分类</th><th>价格</th><th>库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in products.items" :key="p.id"><td><div class="row"><img :src="p.image" :alt="p.name" class="table-image"><strong>{{p.name}}</strong></div></td><td>{{p.category}}</td><td>¥{{money(p.price)}}</td><td>{{p.stock}}</td><td><span class="badge">{{p.listed?'已上架':'已下架'}}</span></td><td><button class="text-button" @click="edit(p)">编辑 →</button></td></tr></tbody></table><p v-if="!products.items.length" class="state">没有匹配商品</p></div><div v-if="tab!=='orders'" class="pagination"><button class="btn secondary small" :disabled="page===1" @click="page--;load()">上一页</button><span>第 {{page}} 页 · 共 {{tab==='users'?users.total:products.total}} 条</span><button class="btn secondary small" :disabled="page*(tab==='users'?10:12)>=(tab==='users'?users.total:products.total)" @click="page++;load()">下一页</button></div><article v-for="o in tab==='orders'?orders:[]" :key="o.id" class="panel order-panel"><div class="row between"><strong>订单 {{o.id.slice(0,8).toUpperCase()}}</strong><span class="badge">{{o.status==='PENDING'?'待付款':labels[o.status]}}</span></div><p>{{o.items.map(i=>i.name+' × '+i.quantity).join('、')}}</p><p class="price">¥{{money(o.payable)}}</p><template v-if="o.recipient"><p>{{o.recipient}} · {{o.phone}}</p><p>{{o.address}}</p></template><p v-else class="hint">未付款或已取消，收货信息不开放。</p><form v-if="o.status==='PAID'" class="filter-bar" @submit.prevent="ship(o)"><input placeholder="承运方" aria-label="承运方" required @input="shipping[o.id]={...shipping[o.id],carrier:$event.target.value}"><input placeholder="物流单号" aria-label="物流单号" required @input="shipping[o.id]={...shipping[o.id],tracking:$event.target.value}"><button class="btn small" :disabled="busy">确认发货</button></form><p v-if="o.carrier">{{o.carrier}} · {{o.tracking}}</p></article></template><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="user-title"><button class="modal-close" aria-label="关闭详情" @click="selected=null">×</button><p class="eyebrow">USER DETAILS</p><h2 id="user-title">{{selected.nickname}}</h2><p>{{selected.account}} · {{selected.role}} · {{labels[selected.status]}}</p><p>{{selected.bio||'尚未填写简介'}}</p><p v-if="selected.latestReason" class="hint">最近处置：{{selected.latestReason}}</p><template v-if="selected.role==='USER'"><hr><h3>{{selected.status==='ACTIVE'?'冻结账号':'解冻账号'}}</h3><form class="form-stack" @submit.prevent="command('state')"><label>处置原因<textarea v-model="reason" required maxlength="200" rows="2"></textarea></label><button class="btn" :disabled="busy">确认{{selected.status==='ACTIVE'?'冻结':'解冻'}}</button></form><hr><h3>发送单用户通知</h3><form class="form-stack" @submit.prevent="command('notification')"><label>标题<input v-model="message.title" required maxlength="60"></label><label>正文<textarea v-model="message.body" required maxlength="500" rows="3"></textarea></label><p class="hint" v-if="selected.status==='FROZEN'">当前被冻结，解冻并重新登录后才能读取通知。</p><button class="btn secondary" :disabled="busy">发送通知</button></form></template></section></div><div v-if="editing" class="modal-backdrop" @click.self="editing=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="product-title"><button class="modal-close" aria-label="关闭编辑" @click="editing=false">×</button><h2 id="product-title">{{editingId?'编辑商品':'新增商品'}}</h2><form class="form-stack" @submit.prevent="saveProduct"><label>名称<input v-model="product.name" required maxlength="100"></label><label>分类<input v-model="product.category" required maxlength="40" list="categories"><datalist id="categories"><option>主粮</option><option>零食</option><option>食具</option><option>玩具</option><option>洗护</option></datalist></label><label>商品说明<textarea v-model="product.description" maxlength="1000"></textarea></label><label>主图<input type="file" accept="image/jpeg,image/png" @change="photo"></label><img v-if="product.image" :src="product.image" alt="商品主图" class="upload-preview"><div class="form-grid"><label>价格（元）<input v-model="priceYuan" inputmode="decimal" required></label><label>库存<input type="number" v-model.number="product.stock" min="0" step="1" required></label></div><label class="checkbox-line"><input type="checkbox" v-model="product.listed">上架商品</label><label class="checkbox-line"><input type="checkbox" v-model="product.recommended">首页推荐</label><button class="btn" :disabled="busy||!product.image">保存商品</button></form></section></div></section></template>
